function saveGame(){if(!state)return;try{localStorage.setItem(saveKey,JSON.stringify({stage:state.stage,talked:state.talked,found:state.found,attempts:state.attempts,hints:state.hints,tripSteps:state.tripSteps}))}catch(e){}}
function loadGame(){try{let s=JSON.parse(localStorage.getItem(saveKey));return s&&[1,2,3].includes(s.stage)&&Array.isArray(s.found)?s:null}catch(e){return null}}
function continueGame(){const saved=loadGame();if(!saved)return;state={...fresh(),stage:saved.stage,talked:!!saved.talked,found:saved.found.filter(id=>evidence.some(e=>e.id===id)),attempts:Number(saved.attempts)||0,hints:Number(saved.hints)||0,tripSteps:Number(saved.tripSteps)||0};enterStage(saved.stage)}
