function fresh(){return {stage:1,x:13,y:83,talked:false,found:[],code:[],walls:[],route:null,visited:[],routeFound:false,modal:false,moveTime:0,attempts:0,hints:0,tripSteps:0}}
function shell(content){app.innerHTML=`<header><div class="brand"><b>✳</b> QAIRU<small>ПОСЛЕДНИЙ СИГНАЛ</small></div><div class="header-right"><span class="status">СИГНАЛ АКТИВЕН</span><button class="bare" id="sound-toggle" aria-label="Включить звуковые эффекты">🔇 ЗВУК</button><button class="bare" id="restart">НАЧАТЬ ЗАНОВО ↗</button></div></header>${content}<div class="bottom"><span>QAIRU · ИСТОРИЯ ОДНОГО ФАЙНАЛА</span><span>УЧЕБНАЯ ИГРА · АСТАНА 2040</span></div>`;bindSound();document.getElementById('restart').onclick=()=>{if(confirm('Начать приключение сначала? Прогресс текущего прохождения исчезнет.'))startGame()}}
function home(){cancelAnimationFrame(loopID);shell(`<main><section class="hero"><div><span class="hero-badge">СТУДЕНЧЕСКОЕ ПРИКЛЮЧЕНИЕ · 3 ГЛАВЫ</span><h1>Последний <span>сигнал</span> Астаны.</h1><p>Завтра файнал. Сегодня городская система ИИ отключилась. А ты просто хотел спокойно доучить Байеса.</p><div class="hero-actions"><button class="button" id="begin">НАЧАТЬ ПРИКЛЮЧЕНИЕ ↗</button>${loadGame()?'<button class="button alt" id="continue">ПРОДОЛЖИТЬ ↗</button>':''}<span class="muted">Браузерная игра · ~10 минут</span></div></div><div class="hero-art"></div></section><div class="overview"><div><strong><b>01 /</b> QAIRU</strong>Выберись из университета</div><div><strong><b>02 /</b> АСТАНА</strong>Найди дорогу к EXPO</div><div><strong><b>03 /</b> EXPO</strong>Раскрой, кто отключил SANA</div></div></main>`);document.getElementById('begin').onclick=startGame;let cb=document.getElementById('continue');if(cb)cb.onclick=continueGame}
const scenes={1:{name:'АУДИТОРИЯ QAIRU',title:'Вечер перед файналом',class:'room',mission:'Найди друга и узнай, что произошло.',dots:[{id:'friend',x:38,y:58,icon:'🧑🏻',name:'Друг'},{id:'laptop',x:19,y:48,icon:'💻',name:'Ноутбук'},{id:'door',x:82,y:53,icon:'🔒',name:'Дверь'}]},2:{name:'НОЧНАЯ АСТАНА',title:'Дорога к EXPO',class:'city',mission:'Подойди к навигатору и найди безопасную дорогу.',dots:[{id:'friend2',x:30,y:54,icon:'🧑🏻',name:'Друг'},{id:'phone',x:50,y:44,icon:'📱',name:'Чат'},{id:'navigator',x:75,y:56,icon:'🗺️',name:'Навигатор'}]},3:{name:'EXPO · СЕРВЕРНАЯ',title:'Последний сигнал',class:'expo',mission:'Найди три улики и проверь версии на терминале.',dots:[...evidence.map(e=>({id:e.id,x:e.x,y:e.y,icon:e.icon,name:e.name})),{id:'board',x:82,y:72,icon:'🔍',name:'Расследование'}]}};
function startGame(){state=fresh();saveGame();enterStage(1,true)}
function enterStage(n,intro=false){clearInterval(routeTimer);cancelAnimationFrame(loopID);keys={};moveTarget=null;arrival=null;state.stage=n;state.x=13;state.y=82;state.modal=false;saveGame();const s=scenes[n];shell(`<main><div class="stage-top"><span class="episode">ГЛАВА 0${n} / 03 &nbsp; · &nbsp; ${s.name}</span><div class="dots"><i class="on"></i><i class="${n>1?'on':''}"></i><i class="${n>2?'on':''}"></i></div></div><div class="play-layout"><div><div class="scene ${s.class}" id="scene"><div class="atmosphere" aria-hidden="true"></div><div class="scene-caption">● &nbsp; ${s.name} &nbsp; / &nbsp; 20:47</div><div class="objective-chip">МИССИЯ 0${n}</div>${s.dots.map(d=>`<button class="hotspot ${state.found.includes(d.id)?'done':''}" data-spot="${d.id}" style="left:${d.x}%;top:${d.y}%" aria-label="${d.name}">${d.icon}<span>${d.name}</span></button>`).join('')}<div class="bot-orb" id="bot"><img src="bot.png" alt="QairuBot"></div><div class="actor" id="actor"><small>ТЫ</small><img src="student.png" alt="Студент"></div><div class="prompt" id="prompt" hidden></div></div><div class="controls"><button data-move="left" aria-label="Влево">◀</button><button data-move="up" aria-label="Вверх">▲</button><button data-move="down" aria-label="Вниз">▼</button><button data-move="right" aria-label="Вправо">▶</button><button class="use" id="act">E · ДЕЙСТВИЕ</button></div></div><aside class="side"><div class="eyebrow">ТВОЯ МИССИЯ</div><h2>${s.title}</h2><div class="quest" id="quest">${s.mission}</div><div class="help">⌨️ <b>WASD / стрелки</b> — движение<br>✋ <b>E</b> — взаимодействовать<br>🖱️ Можно нажимать на объекты</div><div class="character">${n===3?`📁 <b>Журнал улик</b><br>${evidence.map(e=>`${state.found.includes(e.id)?'✓':'○'} ${e.title}`).join('<br>')}`:'🤖 <b>QairuBot</b><br>«Вопросы к ИИ можно задавать. Но сдать файнал за тебя я не могу». '} </div></aside></div></main>`);bindWorld();lastTick=0;loopID=requestAnimationFrame(gameLoop);if(intro)dialog([{who:'ДРУГ',role:'Студент QAIRU',face:'🧑🏻',text:'Бро, ты понял Байеса? Я уже третий раз смотрю объяснение.'},{who:'ТЫ',role:'Студент перед файналом',face:'🧍🏻‍♂️',text:'Почти. Осталось только понять, что такое вероятность.'},{who:'QAIRUBOT',role:'Твой электронный напарник',face:'🤖',text:'Так... свет выключился. А SANA прислала сообщение: «Файнал не отменили. Помогите».'},{who:'ТЫ',role:'План на вечер изменился',face:'🧍🏻‍♂️',text:'Ладно. Сначала найдём друга и попробуем выйти из QAIRU.'}])}
function bindWorld(){if(state.stage===1&&state.talked)document.getElementById('quest').textContent='Подойди к двери и открой замок, используя подсказки.';if(state.stage===3&&state.found.length)document.getElementById('quest').textContent=`Найдено улик: ${state.found.length} / 3. Проверь версии на терминале.`;document.querySelectorAll('[data-spot]').forEach(b=>b.onclick=()=>{let target=scenes[state.stage].dots.find(d=>d.id===b.dataset.spot);moveTarget={x:target.x,y:target.y+9};arrival=()=>interact(target.id)});document.querySelectorAll('[data-move]').forEach(b=>{let key=b.dataset.move;b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[key]=true;moveTarget=null;arrival=null};b.onpointerup=()=>keys[key]=false;b.onpointercancel=()=>keys[key]=false});document.getElementById('act').onclick=useNearest}
function gameLoop(t){if(!state||!document.getElementById('scene'))return;let dt=Math.min((t-(lastTick||t))/1000,.06);lastTick=t;if(!state.modal){let dx=(keys.right||0)-(keys.left||0),dy=(keys.down||0)-(keys.up||0);if(dx||dy){moveTarget=null;arrival=null;let len=Math.hypot(dx,dy);state.x+=dx/len*29*dt;state.y+=dy/len*29*dt}else if(moveTarget){let x=moveTarget.x-state.x,y=moveTarget.y-state.y,dist=Math.hypot(x,y),step=65*dt;if(dist<Math.max(step,.8)){state.x=moveTarget.x;state.y=moveTarget.y;moveTarget=null;let fn=arrival;arrival=null;if(fn)fn()}else{state.x+=x/dist*step;state.y+=y/dist*step}}state.x=Math.max(4,Math.min(96,state.x));state.y=Math.max(35,Math.min(94,state.y))}const a=document.getElementById('actor'),b=document.getElementById('bot');a.classList.toggle('walking',!!(keys.right||keys.left||keys.up||keys.down||moveTarget));a.style.left=state.x+'%';a.style.top=state.y+'%';b.style.left=(state.x-5)+'%';b.style.top=(state.y+3)+'%';const nearest=getNearest(),p=document.getElementById('prompt');p.hidden=!nearest||state.modal||!!moveTarget;if(nearest)p.textContent='E · '+nearest.name;loopID=requestAnimationFrame(gameLoop)}
function getNearest(){return scenes[state.stage].dots.filter(d=>Math.hypot(d.x-state.x,(d.y+9)-state.y)<15).sort((a,b)=>Math.hypot(a.x-state.x,a.y+9-state.y)-Math.hypot(b.x-state.x,b.y+9-state.y))[0]}
function useNearest(){if(state.modal)return;const p=getNearest();if(p)interact(p.id)}
document.addEventListener('keydown',e=>{if(!state||!document.getElementById('scene')||state.modal)return;let map={ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right',ArrowUp:'up',w:'up',ArrowDown:'down',s:'down'};let k=map[e.key]||map[e.key.toLowerCase()];if(k){e.preventDefault();keys[k]=true;moveTarget=null;arrival=null}if((e.key==='e'||e.key==='E')&&!e.repeat)useNearest()});document.addEventListener('keyup',e=>{let map={ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right',ArrowUp:'up',w:'up',ArrowDown:'down',s:'down'};let k=map[e.key]||map[e.key.toLowerCase()];if(k)keys[k]=false});window.addEventListener('blur',()=>keys={});
function overlay(html,wide=false){state.modal=true;keys={};let el=document.createElement('div');el.id='overlay';el.className='screen-overlay';el.innerHTML=`<section class="box ${wide?'wide':''}" role="dialog" aria-modal="true">${html}</section>`;document.body.appendChild(el)}function closeOverlay(){clearInterval(routeTimer);routeBusy=false;document.getElementById('overlay')?.remove();state.modal=false;keys={}}
function dialog(lines,after){let i=0;function paint(){let l=lines[i];let box=document.querySelector('#overlay .box');box.innerHTML=`<div class="dialog-speaker"><div class="avatar">${l.face==='🤖'?'<img src="bot.png" alt="">':l.face==='🧍🏻‍♂️'?'<img src="student.png" alt="">':l.face}</div><div><div class="speaker-name">${l.who}</div><div class="speaker-role">${l.role}</div></div></div><p class="dialog-line">${l.text}</p><div class="dialog-actions"><span class="dialog-count">ДИАЛОГ ${i+1} / ${lines.length}</span><button class="button" id="next-line">${i===lines.length-1?'ПОНЯТНО':'ДАЛЕЕ'} ↗</button></div>`;document.getElementById('next-line').onclick=()=>{i++;if(i===lines.length){closeOverlay();if(after)after()}else paint()}}overlay('');paint()}
function interact(id){if(state.modal)return;if(id==='friend'){state.talked=true;saveGame();document.getElementById('quest').textContent='Подойди к двери и открой замок, используя подсказки.';dialog([{who:'ДРУГ',role:'Одногруппник',face:'🧑🏻',text:'Электронный замок завис! Система просит трёхзначный код. Я нашёл подсказку возле двери.'},{who:'QAIRUBOT',role:'Помощник',face:'🤖',text:'Найдём правильную комбинацию и выберемся. Надеюсь, за это тоже поставят баллы.'}]);return}if(id==='door'){if(!state.talked){dialog([{who:'QAIRUBOT',role:'Помощник',face:'🤖',text:'Сначала спросим друга: он видел, что случилось с замком.'}]);return}openCode();return}if(id==='friend2'){dialog([{who:'ДРУГ',role:'На остановке',face:'🧑🏻',text:'На улице холоднее, чем взгляд препода, когда я сказал «можно я завтра сдам?». Выбирай маршрут на навигаторе.'}]);return}if(id==='laptop'){dialog([{who:'НОУТБУК',role:'Файл «файнал_точно_финал_2»',face:'💻',text:'На экране остался конспект: «CSP — выбери значения, которые не нарушают правила». Кажется, он пригодится.'},{who:'QAIRUBOT',role:'Помощник',face:'🤖',text:'И ещё 47 открытых вкладок. Кажется, ты учился продуктивно.'}]);return}if(id==='phone'){dialog([{who:'ЧАТ ОБЩАГИ',role:'123 новых сообщения',face:'📱',text:'«Кто-нибудь знает, почему отключился интернет? Я почти открыл конспект».',},{who:'ДРУГ',role:'Из общаги',face:'🧑🏻',text:'Я бы помог, но я уже в общаге и снял носки. Удачи вам там!'}]);return}if(id==='navigator'){openRoute();return}let e=evidence.find(e=>e.id===id);if(e){if(!state.found.includes(id)){state.found.push(id);saveGame();}document.querySelector(`[data-spot="${id}"]`)?.classList.add('done');document.getElementById('quest').textContent=`Найдено улик: ${state.found.length} / 3. Проверь версии на терминале.`;let journal=document.querySelector('.side .character');if(journal)journal.innerHTML='📁 <b>Журнал улик</b><br>'+evidence.map(x=>`${state.found.includes(x.id)?'✓':'○'} ${x.title}`).join('<br>');dialog([{who:'НАЙДЕНА УЛИКА',role:e.title,face:e.icon,text:e.text},{who:'QAIRUBOT',role:'Расследование',face:'🤖',text:`Записал. По учебной модели сейчас наиболее вероятен ${people[calculateBelief(state.found).indexOf(Math.max(...calculateBelief(state.found)))]}. Это ещё не доказательство — проверь другие улики.`}]);return}if(id==='board')openCase()}
// CSP: variables are three positions, domains are 1..3, with all-different and clue constraints.
function validCode(a){return a.length===3&&new Set(a).size===3&&a[0]===2&&a[1]>a[2]}function solveCode(prefix=[]){function visit(a){if(a.length===3)return validCode(a)?a:null;for(let d=1;d<=3;d++){if(a.includes(d))continue;let r=visit([...a,d]);if(r)return r}return null}return visit(prefix)}
function openCode(){state.code=[];overlay(`<div class="box-top"><span class="eyebrow">МИНИ-ИГРА 01 · ПОБЕГ ИЗ QAIRU</span><button class="close" onclick="closeOverlay()">✕ Закрыть</button></div><h2>Замок перешёл в режим загадки</h2><p>Дверь заперта. Найди код из трёх цифр и набери его на клавиатуре.</p><div class="keypanel"><div><div class="clue-card"><strong>📄 Записка друга</strong><p>1. В коде цифры <b>1, 2 и 3</b>. Каждая встречается один раз.</p><p>2. Первая цифра — <b>чётная</b>.</p><p>3. Вторая цифра <b>больше третьей</b>.</p></div><div class="feedback" id="code-feedback" aria-live="polite">🤖 Набери три цифры. Если ошибёшься, попробуй ещё раз.</div><div class="controls" style="justify-content:flex-start"><button class="button alt" id="code-hint">💡 Подсказка</button></div></div><div><div class="pass-display" id="pass"></div><div class="keypad"><button data-digit="1">1</button><button data-digit="2">2</button><button data-digit="3">3</button><button class="erase" id="erase">⌫ СТЕРЕТЬ</button><button class="erase" id="reset-code">СБРОС</button><button class="erase" id="code-check">ПРОВЕРИТЬ</button></div></div></div><div id="code-next"></div><details class="explain"><summary>Для защиты: какой алгоритм здесь работает?</summary>CSP: позиции кода — переменные, цифры 1–3 — их возможные значения. Каждая цифра используется один раз, первая равна 2, вторая больше третьей. Подсказка перебирает допустимые варианты и возвращается назад при нарушении ограничений.</details>`);document.querySelectorAll('[data-digit]').forEach(b=>b.onclick=()=>{if(state.code.length<3){state.code.push(Number(b.dataset.digit));renderCode()}});document.getElementById('erase').onclick=()=>{state.code.pop();renderCode()};document.getElementById('reset-code').onclick=()=>{state.code=[];renderCode()};document.getElementById('code-check').onclick=checkCode;document.getElementById('code-hint').onclick=()=>{state.hints++;saveGame();let hint=solveCode(state.code);document.getElementById('code-feedback').textContent=hint?`🤖 Следующая подходящая цифра: ${hint[state.code.length]??'код уже набран'}.`:'🤖 С этими цифрами решения нет. Сотри последнюю и попробуй другой вариант.'};renderCode()}
function renderCode(){document.getElementById('pass').innerHTML=[0,1,2].map(i=>`<div class="digit">${state.code[i]??'·'}</div>`).join('')}
function checkCode(){let f=document.getElementById('code-feedback');if(state.code.length<3){f.textContent='Сначала набери три цифры.';return}state.attempts++;saveGame();if(!validCode(state.code)){f.textContent='Код не подошёл. Проверь все три подсказки и попробуй снова.';return}f.className='feedback good';f.textContent='✓ Замок открыт! QAIRU спасён от ночёвки в аудитории.';document.getElementById('code-next').innerHTML='<button class="button" id="to-city">ВЫЙТИ ИЗ QAIRU ↗</button>';document.getElementById('to-city').onclick=()=>{closeOverlay();enterStage(2);dialog([{who:'ДРУГ',role:'На выходе из QAIRU',face:'🧑🏻',text:'На улице уже Астана: холодно и красиво одновременно.'},{who:'QAIRUBOT',role:'Слабый сигнал',face:'🤖',text:'Последний сигнал SANA идёт от EXPO. Часть дорог закрыта. Подойди к навигатору.'}])}}
const W=8,H=5,startCell=24,goalCell=15,defaultWalls=[3,11,18,19,20,26,34,36,37];
function neighbors(i){let x=i%W,y=Math.floor(i/W);return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,b])=>a>=0&&a<W&&b>=0&&b<H).map(([a,b])=>b*W+a)}
function findRoute(walls,origin=startCell){let blocked=new Set(walls),open=[origin],g=Array(W*H).fill(Infinity),came={},visited=[];g[origin]=0;const h=i=>Math.abs(i%W-goalCell%W)+Math.abs(Math.floor(i/W)-Math.floor(goalCell/W));while(open.length){open.sort((a,b)=>g[a]+h(a)-g[b]-h(b));let u=open.shift();if(visited.includes(u))continue;visited.push(u);if(u===goalCell){let path=[u];while(path[0]!==origin)path.unshift(came[path[0]]);return {path,visited}}for(const v of neighbors(u)){if(blocked.has(v))continue;let cost=g[u]+1;if(cost<g[v]){g[v]=cost;came[v]=u;open.push(v)}}}return {path:null,visited}}
let routePos=startCell,routeSteps=0,routeMode='walk',routeBusy=false;
function openRoute(){if(!state.walls.length)state.walls=[...defaultWalls.filter(i=>i!==26)];state.route=null;state.visited=[];state.routeFound=false;routePos=startCell;routeSteps=0;routeMode='walk';routeBusy=false;overlay(`<div class="box-top"><span class="eyebrow">МИНИ-ИГРА 02 · ПУТЬ К EXPO</span><button class="close" onclick="closeOverlay()">✕ Закрыть</button></div><h2>Найди дорогу к EXPO</h2><p>Проведи QairuBot через город: нажимай на соседние клетки. Закрытые дороги можно открыть в режиме редактирования. Если застрял — попроси бота найти путь.</p><div class="route-layout"><div><div class="route-modes"><button class="route-mode active" id="mode-walk">👟 ИДТИ</button><button class="route-mode" id="mode-edit">🚧 МЕНЯТЬ ДОРОГИ</button></div><div id="map" class="map-grid" role="group" aria-label="Карта улиц Астаны"></div><div class="legend"><span><i style="background:#e6b767"></i> старт / цель</span><span><i style="background:#504149"></i> закрыто</span><span><i style="background:#317474"></i> проверено</span><span><i style="background:#c4ed83"></i> подсказка пути</span></div></div><div><div class="clue-card"><strong>🤖 НАВИГАТОР</strong><p>«Выбирай соседнюю клетку. Я могу найти кратчайший путь, если нужен план».</p><b id="route-steps">ШАГОВ: 0</b></div><div class="route-info" id="route-feedback" aria-live="polite">Нажми на соседнюю клетку, чтобы сделать первый шаг.</div><div class="route-buttons"><button class="button" id="search-route">💡 ПОКАЗАТЬ ПУТЬ</button><button class="button alt" id="reset-map">НАЧАТЬ МАРШРУТ ЗАНОВО</button></div><div id="route-next"></div></div></div><details class="explain"><summary>Для защиты: как здесь работает A*?</summary>A* строит подсказку от текущего положения до EXPO, сравнивая клетки по f = g + h. g — уже пройденное расстояние, h — расстояние по горизонтали и вертикали до цели. Алгоритм обходит закрытые клетки и при одинаковой стоимости шага находит кратчайший маршрут. Карта учебная.</details>`,true);document.getElementById('mode-walk').onclick=()=>setRouteMode('walk');document.getElementById('mode-edit').onclick=()=>setRouteMode('edit');document.getElementById('search-route').onclick=runRoute;document.getElementById('reset-map').onclick=()=>{clearInterval(routeTimer);state.walls=[...defaultWalls.filter(i=>i!==26)];state.route=null;state.visited=[];state.routeFound=false;routePos=startCell;routeSteps=0;routeBusy=false;document.getElementById('route-next').innerHTML='';document.getElementById('route-feedback').textContent='Маршрут сброшен. Выбирай соседние клетки.';setRouteMode('walk')};drawMap()}
function setRouteMode(mode){if(routeBusy)return;routeMode=mode;document.getElementById('mode-walk').classList.toggle('active',mode==='walk');document.getElementById('mode-edit').classList.toggle('active',mode==='edit');document.getElementById('route-feedback').textContent=mode==='walk'?'Нажимай на соседние открытые клетки, чтобы двигаться.':'Нажимай на улицы, чтобы открывать и закрывать их.';drawMap()}
function drawMap(){let map=document.getElementById('map');if(!map)return;document.getElementById('route-steps').textContent=`ШАГОВ: ${routeSteps}`;map.innerHTML=Array.from({length:W*H},(_,i)=>{let current=i===routePos,start=i===startCell,goal=i===goalCell,wall=state.walls.includes(i),on=state.route?.includes(i),seen=state.visited.includes(i),adj=neighbors(routePos).includes(i),cl=current?'current':start?'start':goal?'goal':wall?'wall':on?'path':seen?'visited':'';return `<button class="tile ${cl} ${routeMode==='walk'&&adj&&!wall?'adjacent':''}" data-cell="${i}" aria-label="${current?'QairuBot здесь':goal?'EXPO, цель':start?'QAIRU, начало':wall?'Закрытая улица':'Открытая улица'} ${Math.floor(i/W)+1},${i%W+1}">${current?'🤖':goal?'🌐':start?'🏫':wall?'✕':on?'•':''}</button>`}).join('');map.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>routeClick(Number(b.dataset.cell)))}
function routeClick(i){if(routeBusy||state.routeFound)return;clearInterval(routeTimer);if(routeMode==='edit'){if(i===startCell||i===goalCell||i===routePos){document.getElementById('route-feedback').textContent='Старт, цель и место, где стоит бот, менять нельзя.';return}state.walls=state.walls.includes(i)?state.walls.filter(x=>x!==i):[...state.walls,i];state.visited=[];state.route=null;document.getElementById('route-feedback').textContent=state.walls.includes(i)?'Дорога закрыта. Можно открыть её повторным нажатием.':'Дорога открыта. Вернись в режим «Идти».';drawMap();return}if(!neighbors(routePos).includes(i)){document.getElementById('route-feedback').textContent='Можно идти только на соседнюю клетку: вверх, вниз, влево или вправо.';return}if(state.walls.includes(i)){document.getElementById('route-feedback').textContent='Здесь дорога закрыта. Обойди её или открой в режиме редактирования.';return}routePos=i;routeSteps++;state.tripSteps=routeSteps;state.visited=[];state.route=null;document.getElementById('route-feedback').textContent='Хорошо! Продолжай к 🌐 EXPO.';if(i===goalCell){state.routeFound=true;saveGame();document.getElementById('route-feedback').textContent=`Ты добрался до EXPO за ${routeSteps} шагов!`;document.getElementById('route-next').innerHTML='<button class="button" id="to-expo">ВОЙТИ В EXPO ↗</button>';document.getElementById('to-expo').onclick=()=>{closeOverlay();enterStage(3);dialog([{who:'QAIRUBOT',role:'EXPO',face:'🤖',text:'Мы на месте! В серверной есть камера, журнал доступа и переписка.'},{who:'ТЫ',role:'Расследование',face:'🧍🏻‍♂️',text:'Найдём улики, прежде чем кого-то обвинять. Даже если очень хочется обвинить Wi-Fi.'}])}}drawMap()}
function runRoute(){if(routeBusy||state.routeFound)return;state.hints++;saveGame();clearInterval(routeTimer);let result=findRoute(state.walls,routePos),index=0;state.route=null;state.visited=[];routeBusy=true;document.getElementById('route-feedback').textContent='QairuBot изучает карту...';drawMap();routeTimer=setInterval(()=>{if(!document.getElementById('map')){clearInterval(routeTimer);routeBusy=false;return}if(index<result.visited.length){state.visited.push(result.visited[index++]);drawMap();return}clearInterval(routeTimer);routeBusy=false;if(!result.path){document.getElementById('route-feedback').textContent='Путь закрыт. Выбери «Менять дороги» и открой улицу.';return}state.route=result.path;drawMap();document.getElementById('route-feedback').textContent=`Подсказка готова: до EXPO ${result.path.length-1} шагов. Иди по зелёным клеткам в режиме «Идти».`},35)}
function calculateBelief(found){let p=[1/3,1/3,1/3];for(let id of found){let e=evidence.find(x=>x.id===id);if(!e)continue;p=p.map((v,i)=>v*e.likelihood[i]);let s=p.reduce((a,b)=>a+b,0);p=p.map(x=>x/s)}return p}
function openCase(){let p=calculateBelief(state.found);overlay(`<div class="box-top"><span class="eyebrow">МИНИ-ИГРА 03 · РАССЛЕДОВАНИЕ</span><button class="close" onclick="closeOverlay()">✕ Закрыть</button></div><h2>Кто отключил SANA?</h2><p>Собрано улик: <b>${state.found.length} / 3</b>. Нажми на предметы в серверной, чтобы найти больше. Затем выбери, кому предъявить обвинение.</p><div class="evidence-list">${state.found.length?state.found.map(id=>{let e=evidence.find(x=>x.id===id);return `<div class="evidence-card"><b>${e.icon} ${e.title}</b>${e.text}</div>`}).join(''):'<div class="evidence-card">Пока ни одной улики. Вернись в серверную и осмотри камеру, журнал и переписку.</div>'}</div><div class="eyebrow">ВЕРОЯТНОСТЬ ПО УЧЕБНОЙ МОДЕЛИ</div><div class="bars">${p.map((x,i)=>`<div class="barline"><strong>${people[i]}</strong><div class="barbg"><i style="width:${x*100}%"></i></div><span>${Math.round(x*100)}%</span></div>`).join('')}</div><p>🤖 Это оценка по вымышленным данным, а не доказательство. Обвинить можно и раньше, но можно ошибиться.</p><div class="suspects">${people.map((p,i)=>`<button class="button alt" data-accuse="${i}">${p} ↗</button>`).join('')}</div><details class="explain"><summary>Для защиты: как здесь применяется Байес?</summary>До улик у трёх версий равные вероятности. При каждой найденной улике вероятность версии умножается на вероятность этой улики при данной версии. Затем результат нормируется до 100%. Все вероятности учебные; для упрощения улики считаются условно независимыми.</details>`);document.querySelectorAll('[data-accuse]').forEach(b=>b.onclick=()=>ending(Number(b.dataset.accuse)))}
function ending(suspect){closeOverlay();cancelAnimationFrame(loopID);clearInterval(routeTimer);let good=suspect===0;let total=state.found.length;try{localStorage.removeItem(saveKey)}catch(e){}shell(`<div class="ending"><div class="eyebrow">${good?'МИССИЯ ВЫПОЛНЕНА':'ДЕЛО НЕ ЗАКРЫТО'}</div><h1>${good?'Астана снова на связи.':'Кажется, мы поспешили.'}</h1><p>${good?(total<2?'Ты угадал: Айдар отключил проверку SANA, чтобы скрыть ошибку в проекте. Для надёжного вывода стоило собрать больше улик.':'Айдар отключил проверку SANA, чтобы скрыть ошибку в проекте. Ты собрал доказательства и помог восстановить систему.'):'Ты обвинил '+['Айдара','Дану','Тимура'][suspect]+', но настоящий виновник — Айдар. Он отключил проверку SANA, чтобы скрыть ошибку в проекте. Систему восстановили, но расследование пришлось продолжить.'}</p><div class="clue-card"><strong>🤖 ПОСЛЕДНЕЕ СООБЩЕНИЕ QAIRUBOT</strong><p>«Отличная работа. Кстати, файнал по-прежнему завтра».</p></div><div class="end-stats"><div><strong>${state.attempts}</strong><span>попыток кода</span></div><div><strong>${state.tripSteps}</strong><span>шагов по городу</span></div><div><strong>${total}/3</strong><span>улик найдено</span></div></div><p>Найдено улик: ${total} / 3. ${total<3?'Попробуй найти остальные при следующем прохождении.':'Ты собрал все улики. SANA отправляет секретное сообщение: «Спасибо. И удачи на файнале!»'}</p><button class="button" id="play-again">СЫГРАТЬ ЕЩЁ РАЗ ↗</button></div>`);document.getElementById('play-again').onclick=startGame}

let soundEnabled=false,audioContext=null;
function soundTone(freq=530,duration=.09){if(!soundEnabled)return;try{audioContext=audioContext||new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();let o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.0001,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.035,audioContext.currentTime+.01);g.gain.exponentialRampToValueAtTime(.0001,audioContext.currentTime+duration);o.connect(g);g.connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+duration+.01)}catch(e){}}
function bindSound(){let b=document.getElementById('sound-toggle');if(!b)return;b.textContent=soundEnabled?'🔊 ЗВУК':'🔇 ЗВУК';b.setAttribute('aria-label',soundEnabled?'Выключить звуковые эффекты':'Включить звуковые эффекты');b.onclick=()=>{soundEnabled=!soundEnabled;b.textContent=soundEnabled?'🔊 ЗВУК':'🔇 ЗВУК';b.setAttribute('aria-label',soundEnabled?'Выключить звуковые эффекты':'Включить звуковые эффекты');soundTone(740,.15)}}
document.addEventListener('click',e=>{if(e.target.closest('button')&&e.target.id!=='sound-toggle')soundTone(520,.055)});
